package scale

import "strings"

// The 12-note chromatic scale expressed with sharps and with flats.
var (
	sharpChromatic = []string{"C", "C#", "D", "D#", "E", "F", "F#", "G", "G#", "A", "A#", "B"}
	flatChromatic  = []string{"C", "Db", "D", "Eb", "E", "F", "Gb", "G", "Ab", "A", "Bb", "B"}
)

// Tonics whose scales are written with flats. The natural notes "C" and "a"
// are not listed because, by convention, they follow the sharp scale when
// ascending (the only direction this exercise supports).
var flatTonics = map[string]bool{
	"F": true, "Bb": true, "Eb": true, "Ab": true, "Db": true, "Gb": true,
	"D": true, "G": true,
}

// Scale generates the musical scale starting at the given tonic and
// following the given interval pattern. An empty interval returns the
// full 12-note chromatic scale starting at the tonic.
func Scale(tonic, interval string) []string {
	tonic = normalize(tonic)

	chromatic := sharpChromatic
	if flatTonics[tonic] {
		chromatic = flatChromatic
	}

	start := index(chromatic, tonic)

	if interval == "" {
		result := make([]string, 0, len(chromatic))
		for i := 0; i < len(chromatic); i++ {
			result = append(result, chromatic[(start+i)%len(chromatic)])
		}
		return result
	}

	// Each interval step is a number of half steps on the chromatic scale.
	steps := map[byte]int{'m': 1, 'M': 2, 'A': 3}

	result := []string{tonic}
	pos := start
	for _, r := range interval {
		pos = (pos + steps[r]) % len(chromatic)
		result = append(result, chromatic[pos])
	}
	return result
}

// normalize uppercases the tonic, preserving the lower-case "b" used for flats.
func normalize(tonic string) string {
	if len(tonic) == 2 {
		return strings.ToUpper(tonic[:1]) + tonic[1:]
	}
	return strings.ToUpper(tonic)
}

func index(notes []string, note string) int {
	for i, n := range notes {
		if n == note {
			return i
		}
	}
	return 0
}

