	steps := map[rune]int{'m': 1, 'M': 2, 'A': 3}

	result := []string{tonic}
	pos := start
	for _, r := range interval {
		pos = (pos + steps[r]) % len(chromatic)
		result = append(result, chromatic[pos])
	}
	return result
}

